+// GetInstance returns the singleton for T, creating it with constructor on the first call.
+// Each distinct type, including pointer types, has its own instance.
+func GetInstance[T any](constructor func() T) T {
+	typ := reflect.TypeOf((*T)(nil)).Elem()
+	stored, _ := typedInstances.LoadOrStore(typ, &typedEntry{})
+	e := stored.(*typedEntry)
+	e.once.Do(func() { e.value = constructor() })
+	return e.value.(T)
+}
